import type { Metadata } from "next";
import Image from "next/image";
import Link from "next/link";
import { notFound } from "next/navigation";
import { Badge, Button, Card } from "@/components/ui";
import { getActiveBarbers, getBarberBySlug } from "@/lib/data";
import { getSiteUrl } from "@/lib/seo";
import { getLocale } from "@/lib/i18n/get-dictionary";
import { pickLocalized, pickLocalizedList } from "@/lib/i18n/content";

interface Props {
  params: Promise<{ lang: string; slug: string }>;
}

export const revalidate = 60;

export async function generateMetadata({ params }: Props): Promise<Metadata> {
  const { lang, slug } = await params;
  const locale = getLocale(lang);
  const decodedSlug = decodeURIComponent(slug);
  const barber = await getBarberBySlug(decodedSlug);
  if (!barber) return { title: "Barber not found" };
  const name = pickLocalized(locale, barber.name, barber.nameAm) ?? barber.name;
  const bio = pickLocalized(locale, barber.bio, barber.bioAm);
  return {
    title: `${name} — Barber`,
    description:
      bio?.slice(0, 150) ??
      `Book an appointment with ${name} at Mosisa Barber Shop.`,
    alternates: { canonical: `/barbers/${barber.slug}` },
    openGraph: {
      title: `${name} — Mosisa Barber Shop`,
      description: bio?.slice(0, 200) ?? `Book an appointment with ${name}.`,
      type: "profile",
      url: `/barbers/${barber.slug}`,
      images: barber.photoUrl ? [{ url: barber.photoUrl }] : undefined,
    },
  };
}

export default async function BarberPage({ params }: Props) {
  const { lang, slug } = await params;
  const locale = getLocale(lang);
  const decodedSlug = decodeURIComponent(slug);
  const barber = await getBarberBySlug(decodedSlug);
  if (!barber) notFound();

  const name = pickLocalized(locale, barber.name, barber.nameAm) ?? barber.name;
  const bio = pickLocalized(locale, barber.bio, barber.bioAm);
  const specialties = pickLocalizedList(
    locale,
    barber.specialties,
    barber.specialtiesAm
  );

  const others = (await getActiveBarbers()).filter((b) => b.id !== barber.id);
  const siteUrl = getSiteUrl();

  // JSON-LD: Person + BreadcrumbList (spec §14 — rich results for barber pages)
  const jsonLd = {
    "@context": "https://schema.org",
    "@graph": [
      {
        "@type": "BreadcrumbList",
        itemListElement: [
          { "@type": "ListItem", position: 1, name: "Home", item: siteUrl },
          {
            "@type": "ListItem",
            position: 2,
            name: "Barbers",
            item: `${siteUrl}/barbers`,
          },
          {
            "@type": "ListItem",
            position: 3,
            name,
            item: `${siteUrl}/barbers/${barber.slug}`,
          },
        ],
      },
      {
        "@type": "Person",
        name,
        url: `${siteUrl}/barbers/${barber.slug}`,
        description: bio ?? undefined,
        image: barber.photoUrl ?? undefined,
        jobTitle: "Barber",
        worksFor: {
          "@type": "HairSalon",
          name: "Mosisa Barber Shop",
          url: siteUrl,
        },
      },
    ],
  };

  return (
    <main className="mx-auto max-w-4xl px-4 py-14">
      <script
        type="application/ld+json"
        // JSON.stringify output is escaped here (not v-html) so a bio containing
        // `</script>` cannot break out of the JSON-LD script tag.
        dangerouslySetInnerHTML={{
          __html: JSON.stringify(jsonLd).replace(/</g, "\\u003c"),
        }}
      />

      <div className="grid gap-8 md:grid-cols-[320px_1fr]">
        <div>
          <div className="relative flex aspect-[4/5] items-center justify-center overflow-hidden rounded-lg border border-line bg-gradient-to-br from-forest/40 via-navy/30 to-surface-raised">
            {barber.photoUrl ? (
              <Image
                src={barber.photoUrl}
                alt={`Portrait of ${name}, barber at Mosisa Barber Shop`}
                fill
                sizes="(min-width: 768px) 320px, 100vw"
                quality={90}
                priority
                className="object-cover"
              />
            ) : (
              <span className="font-heading text-7xl font-semibold text-brass/80">
                {name
                  .split(" ")
                  .map((part) => part[0])
                  .slice(0, 2)
                  .join("")}
              </span>
            )}
          </div>

          <Link href={`/book?barber=${barber.slug}`} className="mt-4 block">
            <Button fullWidth>Book with {name.split(" ")[0]}</Button>
          </Link>
        </div>

        <div>
          <h1 className="font-heading text-3xl font-bold sm:text-4xl">
            {name}
          </h1>

          {specialties.length > 0 && (
            <div className="mt-3 flex flex-wrap gap-1.5">
              {specialties.map((specialty) => (
                <Badge key={specialty} tone="forest">
                  {specialty}
                </Badge>
              ))}
            </div>
          )}

          <div className="mt-5 border-t border-line pt-5">
            {bio ? (
              <p className="whitespace-pre-line leading-7 text-cream-muted">
                {bio}
              </p>
            ) : (
              <p className="text-sm italic text-cream-muted">
                Profile coming soon.
              </p>
            )}
          </div>

          {others.length > 0 && (
            <div className="mt-10 border-t border-line pt-6">
              <p className="text-xs font-semibold uppercase tracking-widest text-cream-muted">
                Other barbers
              </p>
              <div className="mt-3 flex flex-wrap gap-2">
                {others.map((other) => (
                  <Link key={other.id} href={`/barbers/${other.slug}`}>
                    <Button variant="ghost" size="sm">
                      {pickLocalized(locale, other.name, other.nameAm) ?? other.name}
                    </Button>
                  </Link>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>
    </main>
  );
}

import type { Metadata } from "next";
import Link from "next/link";
import { Button, Card, StateMessage } from "@/components/ui";
import { getActiveServices } from "@/lib/data";
import { getDictionary, getLocale } from "@/lib/i18n/get-dictionary";
import { localeHref } from "@/lib/i18n/config";
import { pickLocalized } from "@/lib/i18n/content";
import { formatTemplate } from "@/lib/i18n/format";

export async function generateMetadata({
  params,
}: {
  params: Promise<{ lang: string }>;
}): Promise<Metadata> {
  const { lang } = await params;
  const t = await getDictionary(lang);
  const locale = getLocale(lang);
  return {
    title: t.services.title,
    description: `${t.services.subtitle} — ${t.meta.siteName}, ${t.meta.city}.`,
    alternates: {
      canonical: localeHref(locale, "/services"),
      languages: { en: "/en/services", am: "/am/services" },
    },
  };
}

// Services/hours are admin-editable DB content; refresh quickly.
export const revalidate = 60;

export default async function ServicesPage({
  params,
}: {
  params: Promise<{ lang: string }>;
}) {
  const { lang } = await params;
  const [services, t, locale] = await Promise.all([
    getActiveServices(),
    getDictionary(lang),
    getLocale(lang),
  ]);

  return (
    <main className="mx-auto max-w-3xl px-4 py-14">
      <h1 className="font-heading text-3xl font-bold sm:text-4xl">
        {t.services.title}
      </h1>
      <p className="mt-3 text-sm leading-6 text-cream-muted">
        {t.services.subtitle}
      </p>

      <div className="mt-8 flex flex-col gap-3">
        {services.length === 0 ? (
          <Card>
            <StateMessage
              state="empty"
              title={t.services.empty}
              description={t.common.comingSoon}
            />
          </Card>
        ) : (
          services.map((service) => (
            <Card
              key={service.id}
              className="flex flex-wrap items-center justify-between gap-4 p-5"
            >
              <div className="min-w-0">
                <p className="font-medium">
                  {pickLocalized(locale, service.name, service.nameAm)}
                </p>
                {pickLocalized(locale, service.description, service.descriptionAm) && (
                  <p className="mt-1 text-sm leading-6 text-cream-muted">
                    {pickLocalized(locale, service.description, service.descriptionAm)}
                  </p>
                )}
                <p className="mt-1.5 text-xs uppercase tracking-widest text-cream-muted">
                  {service.durationMinutes} {t.services.minutes}
                </p>
              </div>
              <div className="flex shrink-0 items-center gap-4">
                <p className="font-heading text-xl font-semibold text-brass-strong">
                  {service.price ? `${service.price} ${t.common.birr}` : "—"}
                </p>
                <Link href={localeHref(locale, "/book")}>
                  <Button size="sm" variant="secondary">
                    {t.services.bookThis}
                  </Button>
                </Link>
              </div>
            </Card>
          ))
        )}
      </div>
    </main>
  );
}

/**
 * Admin appointments list with filtering (AGENTS.md §6 / Stage 8).
 */
import { Suspense } from "react";
import { getAppointments } from "@/lib/admin-data";
import type { AppointmentList } from "@/lib/admin-data";
import {
  appointmentRangeBounds,
  parseAppointmentRange,
} from "@/lib/admin-ranges";
import { requireAdmin } from "@/components/admin/AdminPageGate";
import { NameCell } from "@/components/admin/NameCell";
import { RangeSelect } from "@/components/admin/RangeSelect";
import { getAdminDictionary, getDictionary, getLocale } from "@/lib/i18n/get-dictionary";
import { localeNames } from "@/lib/i18n/locale-names";
import {
  ADDIS_OFFSET_MS,
  formatAddisDateLabel,
  formatAddisTimeLabel,
  type DateLabelNames,
} from "@/lib/booking/time";
import type { Locale } from "@/lib/i18n/config";
import { Badge, Card, StateMessage } from "@/components/ui";

const STATUS_TONE: Record<string, "brass" | "forest" | "navy" | "warning" | "error" | "neutral"> =
  {
    confirmed: "brass",
    completed: "forest",
    cancelled: "error",
    no_show: "warning",
  };

/** Addis wall-clock parts for a stored instant (Ethiopia is UTC+3 year-round). */
function addisParts(date: Date): { dateKey: string; time: string } {
  const iso = new Date(date.getTime() + ADDIS_OFFSET_MS).toISOString();
  return { dateKey: iso.slice(0, 10), time: iso.slice(11, 16) };
}

/**
 * Full stamp for the table. English keeps the compact staff triage format;
 * Amharic renders the Ethiopian calendar and the 6:00 clock, which already read
 * as local time — so the UTC+3 note is dropped.
 */
function formatAddis(date: Date, names: DateLabelNames): string {
  const { dateKey, time } = addisParts(date);
  return names.ethiopian
    ? `${formatAddisDateLabel(dateKey, names)} ${formatAddisTimeLabel(time, names)}`
    : `${dateKey} ${time} (UTC+3)`;
}

/**
 * Compact Addis Ababa time for the phone card layout: the full
 * "YYYY-MM-DD HH:mm (UTC+3)" string is too long to sit on one card line, so
 * cards show the date once and the start–end times beneath it.
 */
function addisDate(date: Date, names: DateLabelNames): string {
  const { dateKey } = addisParts(date);
  return names.ethiopian ? formatAddisDateLabel(dateKey, names) : dateKey;
}

function addisTime(date: Date, names: DateLabelNames): string {
  return formatAddisTimeLabel(addisParts(date).time, names);
}

export const dynamic = "force-dynamic";
export const runtime = "nodejs";

export default async function AdminAppointmentsPage({
  params,
  searchParams,
}: {
  params: Promise<{ lang: string }>;
  searchParams: Promise<{
    status?: string;
    search?: string;
    dateFrom?: string;
    dateTo?: string;
    range?: string;
  }>;
}) {
  const { lang } = await params;
  const [t, dict] = await Promise.all([
    getAdminDictionary(lang),
    getDictionary(lang),
  ]);
  const locale = getLocale(lang);
  const names = localeNames(locale, dict);
  // The Ethiopian clock reads as local time on its own; only English keeps the
  // UTC+3 note.
  const zoneNote = names.ethiopian ? "" : " (UTC+3)";
  await requireAdmin(lang);
  const sp = await searchParams;
  const status = sp.status as "confirmed" | "cancelled" | "completed" | "no_show" | undefined;
  // A picked range wins over the manual date inputs; submitting the filter form
  // below sends an empty `range` to clear it.
  const range = parseAppointmentRange(sp.range);
  const bounds = range ? appointmentRangeBounds(range) : null;
  const appointments = await getAppointments({
    status,
    search: sp.search,
    dateFrom: bounds?.fromIso ?? sp.dateFrom,
    dateTo: bounds?.toIso ?? sp.dateTo,
  });

  const showStatus = (s: string) =>
    s
      .split(",")
      .map((p) => p.trim())
      .filter(Boolean)
      .join(",");


  return (
    <section className="space-y-6">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <h1 className="font-heading text-xl font-semibold text-cream sm:text-2xl">
          {t.appointments.title}
        </h1>
        <RangeSelect
          value={range ?? "all"}
          t={t.ranges}
          basePath="/admin/appointments"
          preserve={{ status: sp.status, search: sp.search }}
        />
      </div>

      <form className="grid grid-cols-1 gap-3 sm:grid-cols-4 sm:gap-4">
        {/* Clears any picked range so the manual filters apply on their own. */}
        <input type="hidden" name="range" value="" />
        <input
          type="text"
          name="search"
          defaultValue={sp.search}
          placeholder={t.appointments.searchPlaceholder}
          className="h-11 w-full rounded-md border border-line bg-charcoal px-3.5 text-sm text-cream placeholder:text-cream-muted focus:border-brass focus:ring-1 focus:ring-brass/40 focus:outline-none"
        />
        <input
          type="date"
          name="dateFrom"
          defaultValue={sp.dateFrom}
          className="h-11 w-full rounded-md border border-line bg-charcoal px-3.5 text-sm text-cream focus:border-brass focus:ring-1 focus:ring-brass/40 focus:outline-none"
        />
        <input
          type="date"
          name="dateTo"
          defaultValue={sp.dateTo}
          className="h-11 w-full rounded-md border border-line bg-charcoal px-3.5 text-sm text-cream focus:border-brass focus:ring-1 focus:ring-brass/40 focus:outline-none"
        />
        <button
          type="submit"
          className="h-11 w-full rounded-md bg-surface px-4 text-sm font-medium text-cream transition-colors hover:bg-surface-raised sm:w-auto"
        >
          {t.appointments.filter}
        </button>
      </form>

      <Suspense fallback={<StateMessage state="loading" />}>
        <AppointmentsTable
          appointments={appointments}
          t={t}
          locale={locale}
          names={names}
          zoneNote={zoneNote}
        />
      </Suspense>
    </section>
  );
}

async function AppointmentsTable({
  appointments,
  t,
  locale,
  names,
  zoneNote,
}: {
  appointments: AppointmentList[];
  t: Awaited<ReturnType<typeof getAdminDictionary>>;
  locale: Locale;
  names: DateLabelNames;
  /** " (UTC+3)" for English, empty for Amharic (the Ethiopian clock is local). */
  zoneNote: string;
}) {
  if (appointments.length === 0) {
    return <StateMessage state="empty" title={t.appointments.empty} />;
  }

  const statusLabel = (s: string) =>
    ({
      confirmed: t.status.confirmed,
      completed: t.status.completed,
      cancelled: t.status.cancelled,
      no_show: t.status.noShow,
    })[s] ?? s;

  return (
    <Card className="overflow-hidden border-line p-0">
      {/* Wide screens: the full table. */}
      <div className="hidden overflow-x-auto md:block">
        <table className="w-full min-w-[720px] text-sm">
          <thead className="bg-surface">
            <tr>
              <th className="px-4 py-2.5 text-left font-medium text-cream-muted">
                {t.appointments.colWhen}
              </th>
              <th className="px-4 py-2.5 text-left font-medium text-cream-muted">
                {t.appointments.colCustomer}
              </th>
              <th className="px-4 py-2.5 text-left font-medium text-cream-muted">
                {t.appointments.colService}
              </th>
              <th className="px-4 py-2.5 text-left font-medium text-cream-muted">
                {t.appointments.colBarber}
              </th>
              <th className="px-4 py-2.5 text-left font-medium text-cream-muted">
                {t.appointments.colStatus}
              </th>
            </tr>
          </thead>
          <tbody>
            {appointments.map((a) => (
              <tr
                key={a.id}
                className="border-t border-line odd:bg-charcoal even:bg-surface/30"
              >
                <td className="px-4 py-2.5 whitespace-nowrap">
                  {formatAddis(a.startDatetime, names)} →{" "}
                  {formatAddis(a.endDatetime, names)}
                </td>
                <td className="px-4 py-2.5">
                  {a.customerName}
                  <span className="block text-xs text-cream-muted">
                    {a.customerPhone}
                  </span>
                </td>
                <td className="px-4 py-2.5">
                  <NameCell locale={locale} en={a.serviceName} am={a.serviceNameAm} />
                </td>
                <td className="px-4 py-2.5">
                  <NameCell locale={locale} en={a.barberName ?? "—"} am={a.barberNameAm} />
                </td>
                <td className="px-4 py-2.5">
                  <Badge tone={STATUS_TONE[a.status] ?? "neutral"}>
                    {statusLabel(a.status)}
                  </Badge>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Phones: one card per appointment, no horizontal scrolling. */}
      <ul className="divide-y divide-line md:hidden">
        {appointments.map((a) => (
          <li key={a.id} className="space-y-3 p-4">
            <div className="flex flex-wrap items-center justify-between gap-2">
              <div className="min-w-0">
                <span className="block text-sm font-medium text-cream">
                  {addisDate(a.startDatetime, names)}
                </span>
                <span className="text-xs text-cream-muted">
                  {addisTime(a.startDatetime, names)} →{" "}
                  {addisTime(a.endDatetime, names)}
                  {zoneNote}
                </span>
              </div>
              <Badge tone={STATUS_TONE[a.status] ?? "neutral"}>
                {statusLabel(a.status)}
              </Badge>
            </div>

            <dl className="grid grid-cols-[auto_1fr] gap-x-3 gap-y-1.5 text-sm">
              <dt className="text-cream-muted">{t.appointments.customer}</dt>
              <dd className="text-right text-cream">
                {a.customerName}
                <span className="block text-xs text-cream-muted">
                  {a.customerPhone}
                </span>
              </dd>

              <dt className="text-cream-muted">{t.appointments.service}</dt>
              <dd className="text-right text-cream">
                <NameCell locale={locale} en={a.serviceName ?? "—"} am={a.serviceNameAm} />
              </dd>

              <dt className="text-cream-muted">{t.appointments.barber}</dt>
              <dd className="text-right text-cream">
                <NameCell locale={locale} en={a.barberName ?? "—"} am={a.barberNameAm} />
              </dd>
            </dl>
          </li>
        ))}
      </ul>
    </Card>
  );
}

/**
 * Admin dashboard landing (AGENTS.md §6 — Staff can see/operate the shop's
 * appointments; services, barbers, hours, and blocked times are managed on
 * their dedicated pages linked from the sidebar).
 *
 * Reads the appointments for the selected range (?range=today by default,
 * bounded on Addis midnight). Renders an empty state instead of crashing if the
 * DB is unavailable or unseeded.
 */
import { getAppointmentsForRange, type AppointmentList } from "@/lib/admin-data";
import { parseAppointmentRange } from "@/lib/admin-ranges";
import { requireAdmin } from "@/components/admin/AdminPageGate";
import { NameCell } from "@/components/admin/NameCell";
import { RangeSelect } from "@/components/admin/RangeSelect";
import { getAdminDictionary, getDictionary, getLocale } from "@/lib/i18n/get-dictionary";
import { localeNames } from "@/lib/i18n/locale-names";
import { formatTemplate } from "@/lib/i18n/format";
import {
  ADDIS_OFFSET_MS,
  formatAddisDateLabel,
  formatAddisTimeLabel,
  type DateLabelNames,
} from "@/lib/booking/time";
import { Badge, Card, StateMessage } from "@/components/ui";
import { AddToCalendar } from "@/components/admin/AddToCalendar";

const STATUS_TONE: Record<string, "brass" | "forest" | "navy" | "warning" | "error" | "neutral"> =
  {
    confirmed: "brass",
    completed: "forest",
    cancelled: "error",
    no_show: "warning",
  };

/**
 * Addis wall-clock stamp (Ethiopia is UTC+3 year-round). English keeps the
 * compact staff triage format; Amharic renders the Ethiopian calendar and the
 * 6:00 clock, which already read as local time — so the UTC+3 note is dropped.
 */
function formatAddis(date: Date, names: DateLabelNames): string {
  const iso = new Date(date.getTime() + ADDIS_OFFSET_MS).toISOString();
  const dateKey = iso.slice(0, 10);
  const time = iso.slice(11, 16);
  return names.ethiopian
    ? `${formatAddisDateLabel(dateKey, names)} ${formatAddisTimeLabel(time, names)}`
    : `${dateKey} ${time} (UTC+3)`;
}

export default async function AdminDashboardPage({
  params,
  searchParams,
}: {
  params: Promise<{ lang: string }>;
  searchParams: Promise<{ range?: string }>;
}) {
  const { lang } = await params;
  const [t, dict] = await Promise.all([
    getAdminDictionary(lang),
    getDictionary(lang),
  ]);
  const locale = getLocale(lang);
  const names = localeNames(locale, dict);
  // Gate: redirect to the locale-prefixed login page if not authenticated.
  const session = await requireAdmin(lang);
  const sp = await searchParams;
  const range = parseAppointmentRange(sp.range) ?? "today";
  const appointments = await getAppointmentsForRange(range);
  const rangeLabel = t.ranges[range];
  const statusLabel = (s: string) =>
    ({
      confirmed: t.status.confirmed,
      completed: t.status.completed,
      cancelled: t.status.cancelled,
      no_show: t.status.noShow,
    })[s] ?? s;

  return (
    <section className="space-y-8">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <h1 className="font-heading text-xl font-semibold text-cream sm:text-2xl">
          {t.dashboard.headings[range]}
        </h1>
        <RangeSelect
          value={range}
          t={t.ranges}
          basePath="/admin"
          allHrefPath="/admin/appointments"
        />
      </div>

      {appointments.length === 0 ? (
        <StateMessage
          state="empty"
          title={formatTemplate(t.dashboard.emptyTitle, { range: rangeLabel })}
          description={formatTemplate(t.dashboard.emptyBody, {
            range: rangeLabel,
          })}
        />
      ) : (
        <Card className="overflow-hidden border-line p-0">
          {/* Wide screens: the full table. */}
          <div className="hidden overflow-x-auto md:block">
            <table className="w-full min-w-[680px] text-sm">
              <thead className="bg-surface">
                <tr>
                  <th className="px-4 py-2.5 text-left font-medium text-cream-muted">
                    {t.dashboard.colTime}
                  </th>
                  <th className="px-4 py-2.5 text-left font-medium text-cream-muted">
                    {t.dashboard.colCustomer}
                  </th>
                  <th className="px-4 py-2.5 text-left font-medium text-cream-muted">
                    {t.dashboard.colServiceBarber}
                  </th>
                  <th className="px-4 py-2.5 text-left font-medium text-cream-muted">
                    {t.dashboard.colStatus}
                  </th>
                  <th className="px-4 py-2.5 text-left font-medium text-cream-muted">
                    {t.dashboard.colManage}
                  </th>
                </tr>
              </thead>
              <tbody>
                {appointments.map((a) => (
                  <tr
                    key={a.id}
                    className="border-t border-line odd:bg-charcoal even:bg-surface/30"
                  >
                    <td className="px-4 py-2.5 whitespace-nowrap">
