/**
 * Admin working-hours management (AGENTS.md §3 / Stage 8).
 *
 * - GET    /api/admin/working-hours        → list (one row per day_of_week)
 * - POST   /api/admin/working-hours        → upsert all 7 rows from a body of
 *    { "open_0": "09:00", "close_0": "18:00", ... } (day_of_week keyed).
 *
 * POST replaces the whole table in a single transaction so the editor can
 * write all days at once without a multipart key.
 */
import { NextResponse } from "next/server";
import { db } from "@/db/client";
import { workingHours } from "@/db/schema";
import { getSessionFromRequest, requireSession } from "@/lib/admin-guard";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const DAY_NAMES = ["sun", "mon", "tue", "wed", "thu", "fri", "sat"];

export async function GET(request: Request) {
  const session = await getSessionFromRequest(request);
  const unauthorized = requireSession(session);
  if (unauthorized) return unauthorized;

  const all = await db
    .select()
    .from(workingHours)
    .orderBy(workingHours.dayOfWeek);
  return NextResponse.json(all);
}

export async function POST(request: Request) {
  const session = await getSessionFromRequest(request);
  const unauthorized = requireSession(session);
  if (unauthorized) return unauthorized;

  let raw: unknown;
  try {
    raw = await request.json();
  } catch {
    return NextResponse.json({ error: "invalid_json" }, { status: 400 });
  }
  const body = raw as Record<string, unknown>;

  // Build the 7 rows. An empty "open" value for a day means the shop is closed
  // that day (no row inserted).
  const rows: { dayOfWeek: number; startTime: string; endTime: string }[] = [];
  for (let i = 0; i < 7; i++) {
    const open = body[`open_${i}`] as string | undefined;
    const close = body[`close_${i}`] as string | undefined;
    if (open && close) {
      rows.push({
        dayOfWeek: i,
        startTime: open.length >= 5 ? `${open.slice(0, 5)}:00` : open,
        endTime: close.length >= 5 ? `${close.slice(0, 5)}:00` : close,
      });
    }
  }

  try {
    await db.transaction(async (tx) => {
      await tx.delete(workingHours);
      if (rows.length > 0) {
        await tx.insert(workingHours).values(rows);
      }
    });
    return NextResponse.json({ ok: true, rows });
  } catch (err) {
    console.error("[admin working-hours] POST failed:", err);
    return NextResponse.json({ error: "server_error" }, { status: 500 });
  }
}

/**
 * Guest appointment management (AGENTS.md §6, §10).
 *
 *   GET    /api/manage/[token]  → appointment details + late-change status
 *   PATCH  /api/manage/[token]  → reschedule to a new slot
 *   DELETE /api/manage/[token]  → cancel
 *
 * Policy: changes are ALWAYS allowed, even inside the 12-hour window — a late
 * change is flagged (`late_change: true`) and surfaced as a soft warning in the
 * UI, never blocked (spec §4 / §10).
 */
import { NextResponse } from "next/server";
import { and, eq } from "drizzle-orm";
import { db } from "@/db/client";
import { appointments, services } from "@/db/schema";
import { rescheduleInputSchema } from "@/lib/booking/validation";
import {
  cancelAppointmentByToken,
  getAppointmentByToken,
  isOpenForChanges,
} from "@/lib/booking/management";
import { classifyChange } from "@/lib/booking/lateness";
import { formatAddisTime, addisDateKey } from "@/lib/booking/time";
import { sendEmail } from "@/lib/notifications/email";
import { sendSMS } from "@/lib/notifications/sms";

const SIXTY_DAYS_MS = 60 * 24 * 3600 * 1000;

type LoadedAppointment = NonNullable<
  Awaited<ReturnType<typeof getAppointmentByToken>>
>;

/** Shape one appointment for the client. */
function serialize(appointment: LoadedAppointment | null) {
  if (!appointment) return null;
  const startMs = appointment.startDatetime.getTime();
  const change = classifyChange(appointment.startDatetime);
  return {
    appointment_id: appointment.id,
    status: appointment.status,
    source: appointment.source,
    customer_name: appointment.customerName,
    customer_phone: appointment.customerPhone,
    customer_email: appointment.customerEmail,
    start_datetime: appointment.startDatetime.toISOString(),
    end_datetime: appointment.endDatetime.toISOString(),
    display: {
      date_key: addisDateKey(startMs),
      start_time: formatAddisTime(startMs),
      end_time: formatAddisTime(appointment.endDatetime.getTime()),
      timezone: "Africa/Addis_Ababa",
    },
    barber: appointment.barber,
    service: appointment.service,
    can_change: isOpenForChanges(appointment.status),
    late_change: change.isLate,
    late_change_message: change.message,
    hours_until: change.hoursUntil,
  };
}

export async function GET(
  _request: Request,
  { params }: { params: Promise<{ token: string }> }
) {
  const { token } = await params;
  const appointment = await getAppointmentByToken(token);
  if (!appointment) {
    return NextResponse.json(
      { error: "not_found", message: "This appointment link is not valid." },
      { status: 404 }
    );
  }
  return NextResponse.json(serialize(appointment));
}

export async function PATCH(
  request: Request,
  { params }: { params: Promise<{ token: string }> }
) {
  const { token } = await params;

  let raw: unknown;
  try {
    raw = await request.json();
  } catch {
    return NextResponse.json({ error: "invalid_json" }, { status: 400 });
  }

  const parsed = rescheduleInputSchema.safeParse(raw);
  if (!parsed.success) {
    return NextResponse.json(
      { error: "invalid_input", details: parsed.error.issues },
      { status: 400 }
    );
  }
  // Defense in depth: the body token must match the URL token.
  if (parsed.data.management_token !== token) {
    return NextResponse.json(
      { error: "token_mismatch", message: "This link is not valid." },
      { status: 403 }
    );
  }

  const appointment = await getAppointmentByToken(token);
  if (!appointment) {
    return NextResponse.json(
      { error: "not_found", message: "This appointment link is not valid." },
      { status: 404 }
    );
  }
  if (!isOpenForChanges(appointment.status)) {
    return NextResponse.json(
      {
        error: "not_open",
        message:
          appointment.status === "cancelled"
            ? "This appointment has been cancelled. Please book a new one."
            : "This appointment can no longer be changed.",
      },
      { status: 409 }
    );
  }

  const startMs = Date.parse(parsed.data.start_datetime);
  const nowMs = Date.now();
  if (startMs <= nowMs + 60000 || startMs > nowMs + SIXTY_DAYS_MS) {
    return NextResponse.json(
      {
        error: "invalid_slot",
        message: "That time is outside the bookable window.",
      },
      { status: 400 }
    );
  }

  // Duration is always recomputed server-side from the booked service.
  const [service] = await db
    .select()
    .from(services)
    .where(eq(services.id, appointment.service.id))
    .limit(1);
  if (!service) {
    return NextResponse.json({ error: "not_found" }, { status: 404 });
  }

  const newStart = new Date(startMs);
  const newEnd = new Date(startMs + service.durationMinutes * 60 * 1000);
  const change = classifyChange(appointment.startDatetime);

  try {
    await db
      .update(appointments)
      .set({ startDatetime: newStart, endDatetime: newEnd })
      .where(
        and(
          eq(appointments.id, appointment.id),
          eq(appointments.status, "confirmed")
        )
      );
  } catch (error: unknown) {
    const code =
      (error as { code?: string })?.code ??
      (error as { cause?: { code?: string } })?.cause?.code;
    if (code === "23P01") {
      // The exclusion constraint rejected the move — someone else has it.
      return NextResponse.json(
        {
          error: "slot_no_longer_available",
          message:
            "Sorry — that slot was just taken. Please pick another time.",
        },
        { status: 409 }
      );
    }
    console.error("[manage] reschedule failed:", error);
    return NextResponse.json({ error: "server_error" }, { status: 500 });
  }

  // Fire-and-forget notification of the new time (never fails the request).
    const siteUrl = process.env.NEXT_PUBLIC_SITE_URL ?? "";
  const manageUrl = `${siteUrl}/manage/${token}`;
  const newDateKey = addisDateKey(startMs);
  const newStartTime = formatAddisTime(startMs);

  // Email is optional — skip delivery when no address was given at booking.
  if (appointment.customerEmail) {
    const emailResult = await sendEmail(
      appointment.customerEmail,
      `Rescheduled - ${service.name} with ${appointment.barber.name}`,
      `<p>Hi ${appointment.customerName},</p>
     <p>Your appointment has been moved to:</p>
     <p><strong>${newDateKey} at ${newStartTime}</strong> (Harar) with ${appointment.barber.name}</p>
     <p><a href="${manageUrl}">Manage your appointment</a></p>`
    );
    if (!emailResult.success) {
      console.error("[manage] email notification failed:", emailResult.error);
    }
  }

  const smsResult = await sendSMS(
    appointment.customerPhone,
    `Mosisa Barber Shop: moved to ${newDateKey} ${newStartTime}. Manage: ${manageUrl}`
  );
  if (!smsResult.success) {
    console.error("[manage] sms notification failed:", smsResult.error);
  }

  const refreshed = await getAppointmentByToken(token);
  return NextResponse.json({
    ok: true,
    late_change: change.isLate,
    late_change_message: change.message,
    appointment: serialize(refreshed),
  });
}

export async function DELETE(
  request: Request,
  { params }: { params: Promise<{ token: string }> }
) {
  const { token } = await params;

  // Optional body token check (defense in depth) — a body is not required.
  try {
    const raw = (await request.json()) as { management_token?: string };
    if (raw?.management_token && raw.management_token !== token) {
      return NextResponse.json(
        { error: "token_mismatch", message: "This link is not valid." },
        { status: 403 }
      );
    }
  } catch {
    // no body — fine
  }

  const appointment = await getAppointmentByToken(token);
  if (!appointment) {
    return NextResponse.json(
      { error: "not_found", message: "This appointment link is not valid." },
      { status: 404 }
    );
  }

  const result = await cancelAppointmentByToken(token);
  if (result === "not_found") {
    return NextResponse.json({ error: "not_found" }, { status: 404 });
  }
  if (result === "not_open") {
    return NextResponse.json(
      {
        error: "not_open",
        message: "This appointment is already cancelled or completed.",
      },
      { status: 409 }
    );
  }

  const siteUrl = process.env.NEXT_PUBLIC_SITE_URL ?? "";
  const manageUrl = `${siteUrl}/manage/${token}`;
  const dateKey = addisDateKey(appointment.startDatetime.getTime());
  const startTime = formatAddisTime(appointment.startDatetime.getTime());
  const change = classifyChange(appointment.startDatetime);

        // Email is optional — skip delivery when no address was given.
        if (appointment.customerEmail) {
          const emailResult = await sendEmail(            appointment.customerEmail,
            `Cancelled - ${appointment.service.name}`,
            `<p>Hi ${appointment.customerName},</p>
     <p>Your appointment on <strong>${dateKey} at ${startTime}</strong> with ${appointment.barber.name} has been cancelled.</p>
     ${change.isLate
       ? "<p>This was a late cancellation (inside 12 hours). Thanks for letting us know.</p>"
       : ""}
     <p>Book again any time: <a href="${siteUrl}/book">${siteUrl}/book</a></p>`
          );
          if (!emailResult.success) {
            console.error("[manage] email notification failed:", emailResult.error);
          }
        }

  const smsResult = await sendSMS(
    appointment.customerPhone,
    `Mosisa Barber Shop: your ${dateKey} ${startTime} appointment is cancelled. Book again: ${siteUrl}/book`
  );
  if (!smsResult.success) {
    console.error("[manage] sms notification failed:", smsResult.error);
  }

  return NextResponse.json({
    ok: true,
    status: "cancelled",
    late_change: change.isLate,
    late_change_message: change.message,
  });
}

/**
 * Service create/edit form (client component). Posts JSON to the shared
 * /api/admin/services route (POST = create, PATCH = edit). Reuses the
 * existing Input + Button primitives.
 */
"use client";

import { useRouter } from "next/navigation";
import { useState } from "react";
import type { Service } from "@/lib/admin-data";
import { Button, Input, Modal } from "@/components/ui";
import type { Dictionary } from "@/lib/i18n/dictionaries/en";

type ServicesT = Dictionary["admin"]["services"];
type CommonT = Dictionary["admin"]["common"];

async function submit(action: "create" | "edit", payload: Record<string, unknown>, id?: string) {
  const res = await fetch("/api/admin/services" + (id && action === "edit" ? `?id=${id}` : ""), {
    method: action === "create" ? "POST" : "PATCH",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });
  return res;
}

type ServiceValues = {
  name: string;
  nameAm: string;
  description: string;
  descriptionAm: string;
  durationMinutes: string;
  price: string;
  isActive: boolean;
};

export function ServiceForm({
  mode,
  service,
  t,
  common,
}: ({ mode: "create"; service?: undefined } | { mode: "edit"; service: Service }) & {
  t: ServicesT;
  common: CommonT;
}) {
  const router = useRouter();
  const [open, setOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [values, setValues] = useState<ServiceValues>({
    name: service?.name ?? "",
    nameAm: service?.nameAm ?? "",
    description: service?.description ?? "",
    descriptionAm: service?.descriptionAm ?? "",
    durationMinutes: service?.durationMinutes?.toString() ?? "",
    price: service?.price ? Number(service.price).toString() : "",
    isActive: service?.isActive ?? true,
  });

  async function onSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setLoading(true);
    setError(null);
    try {
      const payload = {
        name: values.name,
        nameAm: values.nameAm,
        description: values.description,
        descriptionAm: values.descriptionAm,
        durationMinutes: Number(values.durationMinutes),
        // Blank price → null (service shows no price).
        price: values.price.trim() === "" ? null : values.price.trim(),
        isActive: values.isActive,
      };
      const res = await submit(mode, payload, service?.id);
      if (!res.ok) {
        const body = await res.json().catch(() => ({}));
        setError(body.error ?? `${common.saveFailed} (${res.status})`);
      } else {
        setOpen(false);
        router.refresh();
      }
    } catch (err) {
      setError(common.networkError);
    } finally {
      setLoading(false);
    }
  }

  const trigger = mode === "create" ? (
    <Button variant="primary" size="sm" onClick={() => setOpen(true)}>
      {t.new}
    </Button>
  ) : (
    <Button variant="ghost" size="sm" onClick={() => setOpen(true)}>
      {common.edit}
    </Button>
  );

  return (
    <>
      {trigger}
      <Modal open={open} onClose={() => setOpen(false)} title={mode === "create" ? t.newTitle : t.editTitle}>
        <form onSubmit={onSubmit} className="flex flex-col gap-4">
          {error && (
            <p className="text-sm text-error">{error}</p>
          )}
          <Input
            label={t.name}
            value={values.name}
            onChange={(e) => setValues({ ...values, name: e.target.value })}
            required
          />
          <Input
            label={t.description}
            value={values.description}
            onChange={(e) => setValues({ ...values, description: e.target.value })}
          />
          <p className="text-xs font-semibold uppercase tracking-widest text-cream-muted">
            {common.amharic}
          </p>
          <Input
            label={t.nameAm}
            value={values.nameAm}
            onChange={(e) => setValues({ ...values, nameAm: e.target.value })}
          />
          <Input
            label={t.descriptionAm}
            value={values.descriptionAm}
            onChange={(e) => setValues({ ...values, descriptionAm: e.target.value })}
          />
          <Input
            label={t.duration}
            type="number"
            min={1}
            value={values.durationMinutes}
            onChange={(e) => setValues({ ...values, durationMinutes: e.target.value })}
            required
          />
          <Input
            label={t.price}
            type="number"
            min={0}
            step="0.01"
            value={values.price}
            onChange={(e) => setValues({ ...values, price: e.target.value })}
          />
          <label className="flex items-center gap-2 text-sm">
            <input
              type="checkbox"
              checked={values.isActive}
              onChange={(e) => setValues({ ...values, isActive: e.target.checked })}
            />
            {t.active}
          </label>
          <Button type="submit" variant="primary" fullWidth loading={loading}>
            {loading ? common.saving : mode === "create" ? common.create : common.save}
          </Button>
        </form>
      </Modal>
    </>
  );
}

"use client";

import { Button, Modal } from "@/components/ui";
import { formatAddisTime, addisDateKey } from "@/lib/booking/time";
import { buildIcs, icsDataUrl } from "@/lib/notifications/calendar";

export interface BookingConfirmationModalProps {
  open: boolean;
  onClose: () => void;
  appointmentId: string;
  managementToken: string;
  barberName: string;
  serviceName: string;
  slotIso: string;
  customerName: string;
  customerEmail: string;
  customerPhone: string;
}

/**
 * Compact confirmation modal immediately after booking (spec §8). Full
 * persistent details arrive via email + SMS; the manage link and the .ics
 * download are the fallback if a delivery fails.
 */
export function BookingConfirmationModal({
  open,
  onClose,
  appointmentId,
  managementToken,
  barberName,
  serviceName,
  slotIso,
  customerName,
}: BookingConfirmationModalProps) {
  const siteUrl =
    typeof window !== "undefined"
      ? window.location.origin
      : process.env.NEXT_PUBLIC_SITE_URL ?? "";
  const manageHref = `${siteUrl}/manage/${managementToken}`;

  const ics = buildIcs({
    uid: `${appointmentId}@mosisa-barber-shop`,
    startIso: slotIso,
    endIso: new Date(Date.parse(slotIso) + 60 * 60 * 1000).toISOString(),
    summary: `Appointment — ${serviceName} with ${barberName}`,
    description: `Your appointment at Mosisa Barber Shop.\nManage: ${manageHref}`,
    location: "Mosisa Barber Shop, Harar",
  });

  return (
    <Modal open={open} onClose={onClose} title="Booking confirmed">
      <div className="text-center">
        <span className="font-heading text-4xl" aria-hidden="true">
          ✓
        </span>
        <p className="mt-2 text-sm leading-6 text-cream-muted">
          See you soon, {customerName.split(" ")[0]}.
        </p>
      </div>

      <div className="mt-4 rounded-md border border-line bg-surface p-4 text-sm">
        <p className="font-medium">{serviceName}</p>
        <p className="mt-0.5 text-cream-muted">with {barberName}</p>
        <p className="mt-2">
          {addisDateKey(Date.parse(slotIso))} ·{" "}
          {formatAddisTime(Date.parse(slotIso))}{" "}
          <span className="text-cream-muted">(Harar)</span>
        </p>
      </div>

      <div className="mt-4 grid gap-2">
        <Button
          onClick={() => {
            window.location.href = icsDataUrl(ics);
          }}
        >
          Add to Calendar
        </Button>
        <Button variant="secondary" onClick={() => window.location.assign(manageHref)}>
          Manage appointment
        </Button>
      </div>

      <p className="mt-3 text-center text-xs leading-5 text-cream-muted">
        Confirmation sent to your email and phone. If nothing arrives, use this
        link to manage your booking:{" "}
        <a href={manageHref} className="text-brass-strong underline">
          {manageHref}
        </a>
      </p>
    </Modal>
  );
}

